 for(int i=0;i<4;++i){DrawingDimension d;d.viewId=v.id;d.section=a.curve;d.references={a,b};d.measure=i%2?DrawingMeasure::VerticalDistance:DrawingMeasure::HorizontalDistance;ok(e.addDimension(d,positions[i]));ids.push_back(d.id);}
 e.fitSheet();QApplication::processEvents();require(items(e,"dimensionBadge")==0,"fogli precedenti senza badge");e.markSaved();const auto legacy=encoded(e);const auto legacySchema=QJsonDocument::fromJson(legacy).object()["schema"].toInt();const auto *curve=e.curves(v.id).front().curve.get();DrawingDimensionNumbering setting{true,1,6,3};ok(e.setDimensionNumbering(setting));QApplication::processEvents();const auto numbered=encoded(e);
