 DrawingDimension extra=e.sheet().drawing.dimensions.front();extra.id=QUuid::createUuid();ok(e.addDimension(extra,{20,20}));QApplication::processEvents();require(items(e,"dimensionBadge")==5&&numberBadge(e,extra.id)->data(7).toInt()==1,"inserimento aggiorna tutti i numeri");select(e,extra.id);e.findChild<QAction *>("drawingDeleteSelectionAction")->trigger();QApplication::processEvents();require(items(e,"dimensionBadge")==4&&numberBadge(e,ids[0])->data(7).toInt()==1,"eliminazione compatta la sequenza");ok(e.undo());require(e.sheet().drawing.dimensions.size()==5,"Undo cancellazione ripristina quota numerata");ok(e.undo());require(encoded(e)==numbered,"Undo inserimento ripristina sequenza precedente");QApplication::processEvents();
 // Il badge segue anche le trasformazioni transitorie del testo durante il drag.
